template <class K, class V>
class Memo {
    std::unordered_map<K, V> cache_;
public:
    template <class F>
    const V& get(const K& key, F&& compute) {
        auto it = cache_.find(key);
        if (it == cache_.end()) it = cache_.emplace(key, compute()).first;
        return it->second;   // element references survive rehashing; iterators do not
    }
};

